{
  "name": "USB通信端口组件",
  "name_en": "USB Communication Port Component",
  "manufacturer": "",
  "description": "用于实验系统中通过USB与外部设备交换数据的非物理通信组件。它提供设备枚举、端口打开与关闭、缓冲区查询与清空、字节读写以及字符串读取等基础通信能力，用于承载上层仪器协议。",
  "description_en": "A non-physical communication component used in laboratory systems to exchange data with external devices over USB. It provides basic functions for device enumeration, opening and closing a port, checking and flushing buffers, reading and writing bytes, and reading strings, serving as a transport layer for higher-level instrument protocols.",
  "actions": [
    {
      "action_name": "auto-allDevices",
      "description": "列出可用的USB设备或端口。",
      "description_en": "List available USB devices or ports."
    },
    {
      "action_name": "auto-isOpen",
      "description": "检查USB端口当前是否已打开。",
      "description_en": "Check whether the USB port is currently open."
    },
    {
      "action_name": "auto-isNotOpen",
      "description": "检查USB端口当前是否未打开。",
      "description_en": "Check whether the USB port is currently not open."
    },
    {
      "action_name": "auto-open",
      "description": "打开USB通信端口以开始数据交换。",
      "description_en": "Open the USB communication port to start data exchange."
    },
    {
      "action_name": "auto-close",
      "description": "关闭USB通信端口。",
      "description_en": "Close the USB communication port."
    },
    {
      "action_name": "auto-bytesAvailable",
      "description": "查询指定端点当前可读取的字节数。",
      "description_en": "Query the number of bytes currently available to read on the specified endpoint."
    },
    {
      "action_name": "auto-flush",
      "description": "清空指定端点的通信缓冲区。",
      "description_en": "Flush the communication buffer of the specified endpoint."
    },
    {
      "action_name": "auto-readData",
      "description": "从指定端点读取指定长度的原始数据。",
      "description_en": "Read raw data of the specified length from the specified endpoint."
    },
    {
      "action_name": "auto-writeData",
      "description": "向指定端点写入原始数据。",
      "description_en": "Write raw data to the specified endpoint."
    },
    {
      "action_name": "auto-readString",
      "description": "从指定端点读取字符串数据。",
      "description_en": "Read string data from the specified endpoint."
    }
  ],
  "tag_hints": [
    "USB communication",
    "instrument connectivity",
    "byte stream I/O",
    "device enumeration",
    "endpoint access",
    "protocol transport"
  ]
}

